package main

import (
	"encoding/json"
	"net/http"
	"os"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

var (
	dataStore  []map[string]interface{}
	nextID     = 1
	wsClients  = make(map[*websocket.Conn]bool)
	mu         sync.Mutex
	upgrader   = websocket.Upgrader{CheckOrigin: func(r *http.Request) bool { return true }}
)

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]string{"status": "ok"})
	})

	http.HandleFunc("/data", func(w http.ResponseWriter, r *http.Request) {
		var body map[string]interface{}
		json.NewDecoder(r.Body).Decode(&body)
		body["id"] = nextID
		nextID++
		body["createdAt"] = time.Now().Format(time.RFC3339)
		dataStore = append(dataStore, body)
		msg, _ := json.Marshal(map[string]interface{}{"type": "new_data", "data": body})
		mu.Lock()
		for conn := range wsClients {
			conn.WriteMessage(websocket.TextMessage, msg)
		}
		mu.Unlock()
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(body)
	})

	http.HandleFunc("/data/", func(w http.ResponseWriter, r *http.Request) {
		path := strings.TrimPrefix(r.URL.Path, "/data/")
		id, _ := strconv.Atoi(path)
		for _, item := range dataStore {
			if item["id"] == float64(id) {
				w.Header().Set("Content-Type", "application/json")
				json.NewEncoder(w).Encode(item)
				return
			}
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusNotFound)
		json.NewEncoder(w).Encode(map[string]string{"error": "Not found"})
	})

	http.HandleFunc("/ws", func(w http.ResponseWriter, r *http.Request) {
		conn, _ := upgrader.Upgrade(w, r, nil)
		mu.Lock()
		wsClients[conn] = true
		mu.Unlock()
		conn.WriteMessage(websocket.TextMessage, []byte(`{"type":"connected","message":"Welcome to hybrid API"}`))
		defer func() {
			mu.Lock()
			delete(wsClients, conn)
			mu.Unlock()
			conn.Close()
		}()
		for {
			_, _, _ = conn.ReadMessage()
		}
	})

	http.ListenAndServe(":"+port, nil)
}

