package main

import (
	"encoding/json"
	"net/http"
	"os"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/gorilla/websocket"
)

var (
	dataStore       []map[string]interface{}
	nextID          = 1
	wsClients       = make(map[*websocket.Conn]bool)
	mu              sync.Mutex
	restReqCount    int64
	upgrader        = websocket.Upgrader{CheckOrigin: func(r *http.Request) bool { return true }}
)

func countingHandler(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/stats" {
			atomic.AddInt64(&restReqCount, 1)
		}
		next(w, r)
	}
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	http.HandleFunc("/health", countingHandler(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]string{"status": "ok"})
	}))

