		}
		mu.Unlock()
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(body)
	}))

	http.HandleFunc("/data/", countingHandler(func(w http.ResponseWriter, r *http.Request) {
